    period_name VARCHAR(100) NOT NULL,
    person_id BIGINT NOT NULL REFERENCES person (id),
    amount DECIMAL(15, 2) NOT NULL
);
CREATE INDEX opening_balance_sheet ON opening_balance (sheet_id, period_name);
